import java.util.*;class Solution{int hist(int[]h){Deque<Integer>st=new ArrayDeque<>();int b=0;for(int i=0;i<=h.length;i++){int cur=i==h.length?0:h[i];while(!st.isEmpty()&&h[st.peek()]>cur){int ht=h[st.pop()],l=st.isEmpty()?-1:st.peek();b=Math.max(b,ht*(i-l-1));}st.push(i);}return b;}public int maximalRectangle(char[][]m){if(m.length==0)return 0;int[]h=new int[m[0].length];int b=0;for(char[]r:m){for(int j=0;j<r.length;j++)h[j]=r[j]=='1'?h[j]+1:0;b=Math.max(b,hist(h));}return b;}}
